def _slug(s, n=80):
    s = re.sub(r"[^A-Za-z0-9]+", "-", (s or "")).strip("-")
    return s[:n]


def _doi_tag(doi):
    d = re.sub(r"[^A-Za-z0-9]+", "_", (doi or "").lower()).strip("_")
    return d[:60] or "nodoi"


