def journal_iso4(name):
    n = (name or "").strip().lower()
    if n in JOURNAL_ISO4:
        return JOURNAL_ISO4[n]
    words = re.findall(r"[A-Za-z]{3,}", name or "")
    if len(words) >= 2:
        return "".join(w[0].upper() + "." for w in words[:4]).rstrip(".") or "NA"
    return re.sub(r"[^A-Za-z0-9]", "", name or "")[:16] or "NA"


def _safe_filename(s):
    """把标题/期刊名转成 Windows 合法文件名片段：非法字符转 '-'，压缩空白。

    ⚠️ 只 strip 空白，**不** strip 尾部点：期刊 ISO4 缩写（如 `Nat. Commun.`）
       本就以点结尾，而整条文件名以 `.pdf` 收尾，中段的点是合法的。
       （Windows 只禁止**整条**文件名以点/空格结尾。）
    """
    s = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "-", s or "")
    s = re.sub(r"\s+", " ", s)
    return s.strip()


def pdf_filename(p):
    """按库内约定生成 PDF 文件名：`{标题} - {期刊ISO4} - {年份}.pdf`。

    为何不用 `{doi_tag}__{slug}`：库内 raw/pdf/ 既有 150+ 个 PDF 一律是
    「标题 - 期刊缩写 - 年份」形态（见 raw/pdf/Manual Download/），
    新下载沿用同一形态才能与既有资产并列、便于人工浏览与 ingest 回链。
    """
    title = _safe_filename(p.get("title") or "untitled")
    jrn = _safe_filename(journal_iso4(p.get("journal")))
    date = (p.get("publication_date") or "")
    year = date[:4] if re.match(r"\d{4}", date) else "YYYY"
    return f"{title} - {jrn} - {year}.pdf"


def http_get(url, timeout=45, max_bytes=80 * 1024 * 1024, attempts=3):
    """下载并返回 (bytes, content-type, 最终URL)；调用方负责校验魔数。

    🔴 旧实现**零重试**：出版社 CDN 偶发 429/5xx/超时会让整篇被判「取不到全文」，
    而这是**基础设施故障伪装成内容结论**。现对 429/5xx 与超时/连接错误退避重试
    （1.5s、3s…），对 401/403/404 等 4xx **立即放弃**——重试只会浪费时间并加重风控。
    """
    last = None
    for i in range(max(1, attempts)):
        req = urllib.request.Request(url, headers={
            "User-Agent": UA,
            "Accept": "application/pdf,text/html;q=0.9,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.9",
        })
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                ctype = (r.headers.get("Content-Type") or "").lower()
                buf = b""
                while True:
                    chunk = r.read(65536)
                    if not chunk:
                        break
                    buf += chunk
                    if len(buf) > max_bytes:
                        raise RuntimeError("文件过大，放弃")
                return buf, ctype, r.geturl()
        except urllib.error.HTTPError as e:
            last = e
            retryable = (e.code == 429 or 500 <= e.code < 600)
            if retryable and i < attempts - 1:
                time.sleep(1.5 * (2 ** i))
                continue
            raise
        except RuntimeError:
            raise                       # 「文件过大」不是网络故障，不该重试
        except Exception as e:          # noqa: BLE001  （超时/连接被重置/URLError）
            last = e
            if i < attempts - 1:
                time.sleep(1.5 * (2 ** i))
                continue
            raise
    raise last


def looks_pdf(buf, ctype=""):
    """魔数 + Content-Type 双重判定，**防挑战页伪装成 PDF**。

    🔴 旧实现 `if PDF_MAGIC in head`（前 1KB 内**任何位置**出现 `%PDF` 即判真）过宽：
    Cloudflare 挑战页/HTML 错误页只要正文里带一句 `%PDF` 字样就会被当 PDF 落盘。
    现改为三条同时满足：
      1) 前 1KB 内必须出现完整魔数 `b"%PDF-"`（真 PDF 头，`%PDF` 后必跟 `-`）；
      2) 前 512 字节含 `b"<html"` / `b"<!DOCTYPE"`（大小写不敏感）→ 一律失败；
      3) 响应 Content-Type 含 `text/html` → 一律失败。
    """
    if not buf:
        return False
    head = buf[:1024]
    if PDF_MAGIC not in head:
        return False
    probe = buf[:512].lstrip().lower()
    if b"<html" in probe or b"<!doctype" in probe:
        return False
    if "text/html" in (ctype or "").lower():
        return False
    return True


def json_get(url, timeout=25, attempts=3, ua=None):
    """带退避重试的 JSON GET：429/5xx/超时/连接错误重试，4xx（非 429）立即放弃。

    与 `http_get` 同一套重试纪律，供 Unpaywall 等 JSON 接口复用——
    旧实现里 Unpaywall 是"一次性请求、失败只 warn"，与 `http_get` 的双标准本身
    就是缺陷：同样的网络抖动，下载路径会重试、元数据路径不会。
    """
    last = None
    for i in range(max(1, attempts)):
        req = urllib.request.Request(url, headers={"User-Agent": ua or UA,
                                                  "Accept": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            last = e
            retryable = (e.code == 429 or 500 <= e.code < 600)
            if retryable and i < attempts - 1:
                time.sleep(1.5 * (2 ** i))
                continue
            raise
        except Exception as e:              # noqa: BLE001 （超时/连接被重置/URLError）
            last = e
            if i < attempts - 1:
                time.sleep(1.5 * (2 ** i))
                continue
            raise
    raise last


def _atomic_write_bytes(path, buf):
    """**原子**落盘：先写 `<path>.part`，再 `os.replace` 到正名。

    🔴 为什么必须这样：kill 在 `write_bytes` 中途会留下**半截 PDF**，而文件名已经是
    最终名 ⇒ 下一轮 `fetch_one` 的"已存在 >20KB"分支可能把它当成功跳过，
    去重目录（`lit_catalogue`）也已经把它计入 ⇒ 库里多一篇永远读不出内容的"文献"。
    写 `.part` 则最坏只留一个 `.part`（不是 `.pdf`，不会被任何扫描当成文献）。
    """
    p = Path(path)
    tmp = Path(str(p) + ".part")
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp.write_bytes(buf)
    os.replace(tmp, p)
    return p


def unpaywall_locations(doi, notes=None, cfg=None):
    """返回该 DOI 所有 OA location 的 url_for_pdf / url（按优先级）。

    notes（可选 list）：把"查询失败"的**原因**回填给调用方，让它进失败清单——
    否则 Unpaywall 掉线/限流会被下游读成「该 DOI 没有 OA 版本」，
    又是一次「基础设施故障伪装成内容结论」。
    """
    if not doi:
        return []
    email = contact_email(cfg)
    if not email:
        # 配置里没填真实邮箱 ⇒ **跳过** Unpaywall，而不是编一个假地址（见 contact_email）。
        # 只告警一次，避免每篇候选刷屏。
        if not _UNPAYWALL_WARNED[0]:
            _UNPAYWALL_WARNED[0] = True
            msg = ("datasource.mailto 为空 ⇒ 跳过 Unpaywall 回退（该 API 要求联系邮箱）。"
                   "如需该回退，请在 tools/lit_config.yaml 填真实邮箱。")
            sys.stderr.write(f"[warn] {msg}\n")
            if notes is not None:
                notes.append(msg)
        return []
    url = UNPAYWALL.format(doi=urllib.parse.quote(doi), email=urllib.parse.quote(email))
    try:
        d = json_get(url, timeout=25, attempts=3)
    except Exception as e:                        # noqa: BLE001
        # 不能静默 `return []`：Unpaywall 掉线/限流会被下游读成「该 DOI 没有 OA 版本」。
        # 现在既重试（json_get），也留下带 URL 的告警线索与失败原因。
        msg = (f"Unpaywall 查询失败（已重试 3 次；这是基础设施故障，"
               f"**不等于**该 DOI 没有 OA 版本）：{type(e).__name__}: {e}")
        sys.stderr.write(f"[warn] {msg}\n  url: {url}\n")
        if notes is not None:
            notes.append(msg)
        return []
    out = []
    for loc in (d.get("oa_locations") or []):
        for k in ("url_for_pdf", "url"):
            u = loc.get(k)
            if u and u not in out:
                out.append(u)
    return out


def publisher_direct(doi):
    """出版社/机构**直链形态**（校园网 IP 常可直接取全文）。

    🔴 补的是「声明与实现不一致」：lit-watch/SKILL.md 阶段B 一直声称会
    「尝试拼接机构常用直链形态（pubs.acs.org/doi/pdf/<DOI> 等）」，
    但本脚本 `candidate_urls()` 此前**只试 oa_url / pdf_url / Unpaywall**，
    一条机构直链都没有。

    仍然一律以 `%PDF` 魔数判定真伪——无机构权限时这些直链会返回
    Cloudflare 挑战页或登录页（HTML），不会被误当成 PDF。
    """
    d = (doi or "").strip()
    if not d:
        return []
    q = urllib.parse.quote(d)
    out = [
        f"https://pubs.acs.org/doi/pdf/{q}",
        f"https://onlinelibrary.wiley.com/doi/pdf/{q}",
        f"https://link.springer.com/content/pdf/{q}.pdf",
    ]
    # Nature 系（Nature / Nat. Commun. / npj 等）**直链形态**：
    #   https://www.nature.com/articles/<DOI 后缀>_reference.pdf
    # 实测（2026-10-05）：该形态 200 + %PDF；而 oa_url 给的 https://doi.org/<DOI>
    # 只返回 HTML 落地页 ⇒ 此前 Nat. Commun. 这类**全 OA** 刊反而一篇都下不到。
    if d.lower().startswith("10.1038/"):
        suffix = d.split("/", 1)[1].rstrip(".")
        out.append(f"https://www.nature.com/articles/{suffix}_reference.pdf")
    out.append(f"https://doi.org/{q}")             # 跟随重定向到出版社
    seen, res = set(), []
    for u in out:
        if u not in seen:
            seen.add(u)
            res.append(u)
    return res


def si_candidate_urls(doi):
    """补充材料（SI）的**尽力而为**候选直链（仅 T0/T1 增强精读用）。

    ⚠️ SI 的 URL 形态各出版社差异极大、且多数需登录，命中率天然低——**这是尽力而为**，
    拿不到不算失败（主文照样入库）。一律仍以 `%PDF` 魔数判定真伪。
    形态来源：Wiley `.../doi/suppl/<DOI>/...`、ACS `.../suppl_file/`、Nature
    `<suffix>_MOESM1_ESM.pdf`、RSC `.../suppl/`、Elsevier 需 PII（此处无法推）。
    """
    d = (doi or "").strip()
    if not d:
        return []
    q = urllib.parse.quote(d)
    out = []
    if d.lower().startswith("10.1038/"):
        suffix = d.split("/", 1)[1].rstrip(".")
        out += [f"https://www.nature.com/articles/{suffix}_MOESM1_ESM.pdf",
                f"https://www.nature.com/articles/{suffix}_MOESM2_ESM.pdf"]
    out += [f"https://onlinelibrary.wiley.com/doi/suppl/{q}",
            f"https://pubs.acs.org/doi/suppl/{q}"]
    seen, res = set(), []
    for u in out:
        if u not in seen:
            seen.add(u)
            res.append(u)
    return res


def fetch_si(p, si_dir, hard_timeout=45):
    """尽力尝试下载 SI；成功落 `<si_dir>/<主文 stem>.si.pdf` 并返回路径，否则 None。

    只对增强精读档（T0/T1）调用；失败**静默**（返回 None），不影响主文入库。
    """
    doi = (p.get("doi") or "").strip()
    urls = si_candidate_urls(doi)
    if not urls:
        return None
    try:
        Path(si_dir).mkdir(parents=True, exist_ok=True)
    except Exception:
        return None
    stem = pdf_filename(p)[:-4]
    dest = Path(si_dir) / f"{stem}.si.pdf"
    for u in urls:
        try:
            buf, ctype, final = http_get_guarded(u, hard_timeout=hard_timeout)
        except Exception:
            continue
        if looks_pdf(buf, ctype) and len(buf) > 5000:
            # 原子写（见 _atomic_write_bytes）：SI 半截落盘同样会被当成"已有 SI"
            _atomic_write_bytes(dest, buf)
            return str(dest)
    return None


def candidate_urls(p, institution_proxy=True, notes=None, cfg=None):
    """给一篇候选生成待试 URL 列表（去重、保序）。

    notes（可选 list）会收到 Unpaywall 等**基础设施层**的失败原因，
    最终显示在手动下载清单里（`[]` 不再等于"没有 OA 版本"）。
    """
    urls = []
    for u in [p.get("oa_url") or "", p.get("pdf_url") or ""]:
        if u and u not in urls:
            urls.append(u)
    doi = (p.get("doi") or "").strip()
    if doi:
        for u in unpaywall_locations(doi, notes=notes, cfg=cfg):
            if u not in urls:
                urls.append(u)
        if institution_proxy:
            for u in publisher_direct(doi):
                if u not in urls:
                    urls.append(u)
    return urls


def _si_step(pdf_path, si_dir):
    """判定 + 尝试取 SI（委托 lit_si；任何异常都降级为 unknown，不阻断主流程）。

    返回 lit_si.fetch 的结果 dict；lit_si 不可用时返回 {"status": "unknown"}。
    """
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import lit_si
        return lit_si.fetch(pdf_path, si_dir=str(si_dir), apply=True, verbose=False)
    except Exception as e:                                     # noqa: BLE001
        return {"status": "unknown", "reason": f"lit_si 不可用：{type(e).__name__}: {e}"}


def _dl_worker(u, box, idx):
    """在线程里下载单个 URL，结果（bytes/ctype/url 或异常）放回 box[idx]。

    线程无法被强杀，但主线程可以不等它——卡住的线程留作 daemon，进程退出时一并回收。
    这样单篇坏 URL 永远不会拖死整批。
    """
    try:
        buf, ctype, final = http_get(u)
        box[idx] = (buf, ctype, final, None)
    except Exception as e:
        box[idx] = (None, "", "", e)


def http_get_guarded(url, hard_timeout=75):
    """带硬超时的下载：超 hard_timeout 秒即放弃该 URL（不等线程）。"""
    import threading
    box = {}
    t = threading.Thread(target=_dl_worker, args=(url, box, 0), daemon=True)
    t.start()
    t.join(hard_timeout)
    if 0 not in box:
        raise TimeoutError(f"超过 {hard_timeout}s 未完成，放弃")
    buf, ctype, final, err = box[0]
    if err:
        raise err
    return buf, ctype, final


def _is_http_url(u):
    """只接受 http(s) 协议：外部 JSON 里的 URL 不可直接采信。

    `file:///C:/...` 之类会被 urlopen 正常打开，从而把本机任意文件当"PDF 下载成功"。
    """
    return bool(re.match(r"^https?://", str(u or "").strip(), re.I))


def result_runs_dir(outdir, cfg=None):
    """结果 JSON 的落点目录：优先 lit 配置的 runs_dir，取不到退回 outdir.parent。"""
    if cfg is None:
        try:
            cfg = K.load_lit_config()
        except Exception:                        # noqa: BLE001
            cfg = {}
    d = (cfg.get("paths") or {}).get("runs_dir") or ""
    return Path(d) if d else Path(outdir).parent


def manual_inbox(cfg=None):
    """手动下载的**真收件箱**：`<paths.pdf_dir>/Manual Download`。

    ⚠️ 不是 `paths.download_dir`：按 `lit_config.yaml` 的注释，后者是"被墙件**清单**"的落点，
    PDF 收件箱另有其处（`lit_manual_import.DEFAULT_INBOX` = `raw/pdf/Manual Download`）。
    清单里写给用户看的落点必须是**真收件箱**，否则用户按指引放好文件、收编脚本一个也扫不到。
    """
    if cfg is None:
        try:
            cfg = K.load_lit_config()
        except Exception:                        # noqa: BLE001
            cfg = {}
    pdf_dir = ((cfg.get("paths") or {}).get("pdf_dir")
               or K.LIT_CONFIG_DEFAULTS["paths"]["pdf_dir"])
    return os.path.join(pdf_dir, "Manual Download")


def _head_bytes(path, n=1024):
    """读文件头 n 字节（判魔数用，不整读大文件）。"""
    try:
        with open(path, "rb") as f:
            return f.read(n)
    except Exception:                            # noqa: BLE001
        return b""


def fetch_one(p, outdir, tried_log, institution_proxy=True, cfg=None):
    """尝试下载一篇；成功返回 (path, url)，失败返回 (None, [原因])。

    institution_proxy 由调用方从配置 `defaults.institution_proxy`（默认 True）传入——
    旧实现该参数**从来没有被传过**，于是配置里的开关改不动任何行为
    （"配置里写着却没人读"比没有更坏：改它的人以为生效了）。
    """
    doi = (p.get("doi") or "").strip()
    title = p.get("title") or ""
    fname = pdf_filename(p)
    dest = Path(outdir) / fname
    if dest.exists() and dest.stat().st_size > 20000:
        # 🔴 旧实现只看 >20KB 就认定「完好」：一个 20KB 的 HTML 错误页（或截断文件）
        #    会被**永久跳过**、并算作成功。补一次 `%PDF-` 魔数校验，不真就重下。
        if looks_pdf(_head_bytes(dest)):
            return dest, "已存在(跳过下载)"
        print(f"[warn] 已存在文件不是真 PDF（{dest.stat().st_size}B），重新下载：{fname}",
              file=sys.stderr)

    notes = []          # 基础设施层失败（Unpaywall 等）也要进失败原因
    urls = candidate_urls(p, institution_proxy=institution_proxy, notes=notes, cfg=cfg)
    reasons = list(notes)
    for u in urls:
        # 🔴 外部 URL 的 scheme 不可直接采信：`file:///` 之类会被 urlopen 打开并
        #    "下载成功"（把本机任意文件当文献落盘）。只接受 http(s)。
        if not _is_http_url(u):
            reasons.append(f"{str(u)[:70]} → 非 http(s) 协议，拒绝")
            continue
        try:
            buf, ctype, final = http_get_guarded(u)
        except Exception as e:
            reasons.append(f"{u[:70]} → {type(e).__name__}: {str(e)[:60]}")
            continue
        if looks_pdf(buf, ctype):
            # 原子写（见 _atomic_write_bytes）：中途被杀不会留下半截 .pdf
            _atomic_write_bytes(dest, buf)
            tried_log.append({"doi": doi, "url": final, "ok": True})
            return dest, final
        reasons.append(f"{u[:70]} → 非PDF(ctype={ctype[:40]}, {len(buf)}B)")
    tried_log.append({"doi": doi, "ok": False, "reasons": reasons})
    return None, reasons


def _title_search_link(title):
    """无 DOI / 无直链时的兜底可点击链接。

    2026-10-22 定规：**凡是要人手动下载的条目，必须带可点击链接**——
    只给标题等于让人自己去猜。DOI 缺失时给按标题的检索链接，仍满足"可点击"。
    """
    q = urllib.parse.quote_plus((title or "").strip()[:200])
    return f"https://scholar.google.com/scholar?q={q}"


def write_manifest(failed, path, label, download_dir, si_failed=None):
    lines = [f"# lit-watch 手动下载清单 · {label}", ""]
    lines.append(f"> 生成日期：{datetime.date.today().isoformat()}")
    if failed:
        lines.append("> 下列文献阶段A已锁定方向，但阶段B 自动取全文失败（付费墙 / 风控挑战页 / 非PDF）。")
        lines.append("> 请在浏览器点开 DOI 或直链下载 PDF，放入：")
        lines.append(f"> `{download_dir}`")
    if si_failed:
        lines.append(">")
        lines.append("> **📎 另有 %d 篇主文已下到、但补充材料（SI）没取到**——见文末「SI 待手动下载」。"
                     % len(si_failed))
        lines.append("> SI 放 `raw/pdf/si/<与主文同名>.si.<pdf|docx>`（`lit_si` 与 `lit_ingest` 都按这个名字找）。")
    lines.append("")
    for i, (p, reasons) in enumerate(failed, 1):
        doi = p.get("doi") or ""
        lines.append(f"### {i}. {p.get('title','')}")
        lines.append(f"- **期刊**：{p.get('journal','')}（{p.get('publication_date','')}）")
        lines.append(f"- **主要作者**：{p.get('main_authors','—')}")
        lines.append(f"- **通讯作者**：{p.get('corresponding_author','—')}")
        if doi:
            lines.append(f"- **DOI**：[{doi}](https://doi.org/{doi})")
        if not (doi or p.get("oa_url") or p.get("pdf_url")):
            lines.append(f"- **按标题检索**：[Google Scholar]({_title_search_link(p.get('title'))})")
        if p.get("oa_url"):
            lines.append(f"- **OA 页**：[打开]({p.get('oa_url')})")
        if p.get("pdf_url"):
            lines.append(f"- **PDF 直链**：[点击下载]({p.get('pdf_url')})")
        lines.append(f"- 自动失败原因：`{(reasons[0] if isinstance(reasons, list) and reasons else str(reasons))[:120]}`")
        lines.append("")

    # —— 📎 SI 待手动下载（2026-10-22 定规：有 SI 但取不到，必须在这里提醒）
    if si_failed:
        lines.append("---")
        lines.append("")
        lines.append("## 📎 SI 待手动下载")
        lines.append("")
        lines.append("> 这 %d 篇**主文已入库**，但补充材料按当前通道取不到（反爬/需登录）。"
                     % len(si_failed))
        lines.append("> 全文里已确认它们**确有 SI**；取到后放到 `raw/pdf/si/`，"
                     "命名 `<与主文同名>.si.<pdf|docx|xlsx>`。")
        lines.append("")
        for i, (p, r) in enumerate(si_failed, 1):
            doi = p.get("doi") or ""
            sc = r.get("scan") or {}
            lines.append(f"### S{i}. {p.get('title','')}")
            lines.append(f"- **期刊**：{p.get('journal','')}（{p.get('publication_date','')}）")
            if doi:
                lines.append(f"- **DOI**：[{doi}](https://doi.org/{doi})")
            else:
                lines.append(f"- **按标题检索**：[Google Scholar]({_title_search_link(p.get('title'))})")
            if doi and doi.lower().startswith("10.1021/"):
                lines.append(f"- **SI 页**：[ACS SI 专题页](https://pubs.acs.org/doi/suppl/{doi})")
            elif doi and doi.lower().startswith("10.1126/"):
                lines.append(f"- **SI 页**：[Science SI 页](https://www.science.org/doi/suppl/{doi})")
            elif doi and doi.lower().startswith("10.1038/"):
                lines.append("- **SI 页**：文章页底部 **Supplementary information**")
            # 若是 Wiley 且扫描到了文件名，给文件级直链
            for fn in (sc.get("filenames") or [])[:3]:
                if doi:
                    lines.append(f"- **SI 直链**：[⬇ {fn}]"
                                 f"(https://onlinelibrary.wiley.com/action/downloadSupplement?"
                                 f"doi={urllib.parse.quote(doi, safe='')}&file={urllib.parse.quote(fn, safe='')})")
            if doi and doi.lower().startswith("10.1002/") and not (sc.get("filenames") or []):
                lines.append(f"- **SI 区**：[Wiley Supporting Information]"
                             f"(https://onlinelibrary.wiley.com/doi/{doi}#support-information-section)")
            if doi and doi.lower().startswith("10.1149/"):
                lines.append(f"- **SI 页**：[IOP suppdata](https://iopscience.iop.org/article/{doi}/suppdata)")
            if doi and doi.lower().startswith("10.1039/"):
                # RSC 的 article-supplement 直链需文章页上的编号，**不可由 DOI 推导** ⇒ 只给 DOI，
                # 并注明去文章页文末取「Supplementary information」（不编造 URL）
                lines.append("- **RSC 取法**：文章页文末 **Supplementary information**（新版 `article-supplement/…` 直链只在该页出现）")
            ev = (sc.get("evidence") or [""])[0]
            if ev:
                lines.append(f"- 判定依据：`{ev[:140]}`")
            if r.get("reason"):
                lines.append(f"- 自动失败：`{r['reason'][:100]}`")
            lines.append("")

    # 🔴 父目录不存在时 write_text 直接 FileNotFoundError（--manifest 常指向尚未创建的目录）
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    txt = "\n".join(lines)
    # 🔴 写后复算（2026-10-22 定规：手动下载项**必须**带可点击链接）。
    #    按 `### ` 切块逐块数有没有 `](http`——没有就是"只给了标题，让人自己去找"，等于没给。
    blocks = re.split(r"(?m)^### ", txt)[1:]
    linkless = [b.splitlines()[0].strip() for b in blocks if "](http" not in b]
    if linkless:
        print(f"[warn] 手动下载清单有 {len(linkless)} 条没有下载链接：{linkless[:3]}")
    Path(path).write_text(txt, encoding="utf-8")
    return str(Path(path))


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    `looks_pdf` 是本管线**唯一的真伪闸门**——它误判为 True 就会把
    Cloudflare 拦截页 / HTML 错误页当成 PDF 落盘（本脚本 docstring 明载的失效模式），
    误判为 False 则会把真 PDF 丢掉。故两个方向都必须有夹具。
    """
    ok = True
    cases = [
        (b"%PDF-1.7\n...", "", True, "正例 标准 %PDF 头"),
        (b"  \n%PDF-1.4", "", True, "正例 前导空白后 %PDF"),
        (b"\xef\xbb\xbf%PDF-1.4", "application/pdf", True, "正例 BOM + Content-Type"),
        (b"", "", False, "反例 空缓冲"),
        (b"<html><body>cf-error</body></html>", "text/html", False, "反例 HTML 拦截页"),
        # 🔴 以下三条是本轮修复的核心（旧实现全部误判为真 PDF）：
        (b"<html>some text mentioning %PDF inside html</html>", "", False,
         "反例 HTML 正文内嵌 %PDF 字样（旧实现判真，现必须判失败）"),
        (b"<!DOCTYPE html><html>cf challenge %PDF-1.7</html>", "", False,
         "反例 DOCTYPE 挑战页带完整魔数"),
        (b"%PDF-1.4 fake header but served as html", "text/html; charset=utf-8", False,
         "反例 Content-Type=text/html 一律失败"),
    ]
    for buf, ctype, want, label in cases:
        got = looks_pdf(buf, ctype)
        print(f"  [{'ok' if got == want else 'FAIL'}] {label} -> {got}")
        ok = ok and got == want

    # 魔数必须完整：只有 `%PDF` 三个字节（无 `-`）不足以判定
    got = looks_pdf(b"junk %PDF junk junk")
    print(f"  [{'ok' if not got else 'FAIL'}] 反例 非完整魔数 `%PDF`（无 -）不判真 -> {got}")
    ok = ok and not got
    # 真 PDF 头落在 1KB 内但被一堆前导空白/注释推到 512B 之后仍须放行
    got = looks_pdf(b" " * 600 + b"%PDF-1.5\nbody")
    print(f"  [{'ok' if got else 'FAIL'}] 正例 前导空白 600B 后的完整魔数仍放行 -> {got}")
    ok = ok and got

    # publisher_direct：Nature 系直链形态（2026-10-05 回归夹具）
    # 正例：10.1038/* 必须生成 <suffix>_reference.pdf 直链
    nat = publisher_direct("10.1038/s41467-026-78268-4")
    want_nat = "https://www.nature.com/articles/s41467-026-78268-4_reference.pdf"
    mark = "ok" if want_nat in nat else "FAIL"
    print(f"  [{mark}] Nature 直链生成 -> {want_nat in nat}")
    ok = ok and want_nat in nat
    # 反例：非 10.1038/* 不得生成 nature.com 直链（避免误拼）
    acs = publisher_direct("10.1021/acsnano.6c10344")
    mark = "ok" if not any("nature.com" in u for u in acs) else "FAIL"
    print(f"  [{mark}] 反例 非 Nature DOI 不生成 nature.com 直链 -> "
          f"{not any('nature.com' in u for u in acs)}")
    ok = ok and not any("nature.com" in u for u in acs)

    # pdf_filename：库内命名约定 `{标题} - {期刊ISO4} - {年份}.pdf`
    cases_fn = [
        ({"title": "Exploring Li growth modes in Li metal electrodes",
          "journal": "Nature Communications", "publication_date": "2026-09-29"},
         "Exploring Li growth modes in Li metal electrodes - Nat. Commun. - 2026.pdf"),
        # 反例：Windows 非法字符（: / ?）必须被替换、且不残留
        ({"title": "Data: a case/study? of AI",
          "journal": "npj Computational Materials", "publication_date": "2026-01-01"},
         "Data- a case-study- of AI - npj Comput. Mater. - 2026.pdf"),
    ]
    for meta, want in cases_fn:
        got = pdf_filename(meta)
        mark = "ok" if got == want else "FAIL"
        print(f"  [{mark}] pdf_filename -> {got!r}")
        ok = ok and got == want
    bad = pdf_filename({"title": "a:b/c?d*e", "journal": "Nature", "publication_date": ""})
    mark = "ok" if not any(ch in bad for ch in ':*/?') else "FAIL"
    print(f"  [{mark}] 反例 文件名不含 Windows 非法字符 -> {bad!r}")
    ok = ok and not any(ch in bad for ch in ':*/?')

    # si_candidate_urls（2026-10-06 增强精读回归夹具）
    # 正例：Nature 系必须给出 MOESM1 SI 直链
    siu = si_candidate_urls("10.1038/s41467-026-78268-4")
    want_si = "https://www.nature.com/articles/s41467-026-78268-4_MOESM1_ESM.pdf"
    mark = "ok" if want_si in siu else "FAIL"
    print(f"  [{mark}] SI Nature 直链 -> {want_si in siu}")
    ok = ok and want_si in siu
    # 反例：空 DOI 不得生成任何 SI 候选
    mark = "ok" if si_candidate_urls("") == [] else "FAIL"
    print(f"  [{mark}] 反例 空 DOI → 无 SI 候选 -> {si_candidate_urls('') == []}")
    ok = ok and si_candidate_urls("") == []

    # _is_http_url：只放行 http(s)，file:/// 等一律拒绝（防本机文件被当"下载成功"）
    for u, want in (("https://x.org/a.pdf", True), ("http://x.org/a.pdf", True),
                    ("file:///C:/Windows/win.ini", False), ("ftp://x.org/a.pdf", False),
                    ("", False), ("javascript:alert(1)", False)):
        got = _is_http_url(u)
        print(f"  [{'ok' if got == want else 'FAIL'}] _is_http_url {u!r} -> {got}")
        ok = ok and got == want

    # 联系邮箱：只能来自配置；**源码里不得再出现任何假邮箱字面量**（2026-10-10 回归夹具）
    ok_mail = (contact_email({"datasource": {"mailto": "real@lab.edu"}}) == "real@lab.edu"
               and contact_email({"datasource": {"mailto": ""}}) == ""
               and contact_email({"datasource": {}}) == "")
    print(f"  [{'ok' if ok_mail else 'FAIL'}] contact_email 只认配置（空配置→空串）")
    ok = ok and ok_mail
    src = Path(__file__).read_text(encoding="utf-8")
    # 反例：模块里不得再有写死的联系邮箱**常量**（假邮箱只能来自配置）。
    # 注：docstring/注释里保留 "旧实现写死 <假邮箱>" 的说明是有意的（记录踩过的坑），
    #     故这里查的是"可被引用的常量"与"会被发出去的 UA/URL"，不是全文 grep。
    no_const = "CONTACT_EMAIL" not in globals()
    print(f"  [{'ok' if no_const else 'FAIL'}] 反例 模块已无 CONTACT_EMAIL 常量")
    ok = ok and no_const
    fake = "exa" + "mple.org"          # 拼出来，避免本夹具自己成为"源码里的假邮箱"
    good = fake not in contact_email({}) and fake not in contact_email(None)
    print(f"  [{'ok' if good else 'FAIL'}] 反例 取到的邮箱绝不等于占位地址")
    ok = ok and good
    # 配置里没邮箱时必须**跳过** Unpaywall 并给出原因（而不是编地址 / 静默 return []）
    nts = []
    got_u = unpaywall_locations("10.1038/x", notes=nts,
                                cfg={"datasource": {"mailto": ""}})
    good = got_u == [] and nts and "mailto" in nts[0]
    print(f"  [{'ok' if good else 'FAIL'}] 空 mailto → 跳过 Unpaywall 且带原因 -> {nts}")
    ok = ok and good

    # 手写收件箱必须是真收件箱（<pdf_dir>/Manual Download），不是 paths.download_dir
    inbox = manual_inbox({"paths": {"pdf_dir": "raw/pdf"}})
    good = inbox.replace("\\", "/").endswith("raw/pdf/Manual Download")
    print(f"  [{'ok' if good else 'FAIL'}] manual_inbox 由 pdf_dir 派生 -> {inbox}")
    ok = ok and good

    # 原子写：落正名、不留 .part（半截文件不得以最终名出现）
    import tempfile
    at_dir = K.make_temp_dir(prefix="lit_fetch_atomic_")
    try:
        ap = Path(at_dir) / "x.pdf"
        _atomic_write_bytes(ap, b"%PDF-1.7 atomic")
        good = ap.exists() and ap.read_bytes() == b"%PDF-1.7 atomic" \
            and not Path(str(ap) + ".part").exists()
        print(f"  [{'ok' if good else 'FAIL'}] _atomic_write_bytes 落正名且无 .part 残留")
        ok = ok and good
        # 反例：looks_pdf 必须能认出它（写着 .pdf 不等于真 PDF 的教训）
        good = looks_pdf(_head_bytes(ap))
        print(f"  [{'ok' if good else 'FAIL'}] _head_bytes + looks_pdf 复判原子写入的文件")
        ok = ok and good
    finally:
        import shutil as _sh
        _sh.rmtree(at_dir, ignore_errors=True)

    # result_runs_dir：必须落在 lit 配置的 runs_dir（而非 outdir.parent 漂移）
    try:
        want_runs = (K.load_lit_config().get("paths") or {}).get("runs_dir") or ""
    except Exception:                            # noqa: BLE001
        want_runs = ""
    got_runs = str(result_runs_dir(Path("some/outdir")))
    good = (os.path.abspath(got_runs) == os.path.abspath(want_runs)) if want_runs \
        else got_runs.replace("\\", "/").endswith("some")
    print(f"  [{'ok' if good else 'FAIL'}] result_runs_dir 取 runs_dir -> {got_runs}")
    ok = ok and good

    # write_manifest：父目录不存在时必须自建（否则 FileNotFoundError）
    # ⚠️ 探针目录**不得落在 tools/**：旧版写 `Path(__file__).parent/_selftest_*/sub`，
    #    自检被杀（Ctrl-C / 超时）时会在工具目录里留下 `_selftest_*` 垃圾目录。
    #    逐级回退 temp → cwd → 工具目录，并**实写一个文件**探测可写性
    #    （受限环境下 `mkdtemp` 可能"能建目录但不能写文件"）。与 lit_doctor/lit_daily 同一写法。
    import shutil
    import tempfile
    import uuid
    base_tmp = ""
    for base in (tempfile.gettempdir(), os.getcwd(), os.path.dirname(os.path.abspath(__file__))):
        cand = os.path.join(base, "lit_fetch_selftest")
        try:
            shutil.rmtree(cand, ignore_errors=True)
            os.makedirs(cand, exist_ok=True)
            probe_f = os.path.join(cand, ".w")
            with open(probe_f, "w", encoding="utf-8") as fh:
                fh.write("x")
            os.remove(probe_f)
            base_tmp = cand
            break
        except OSError:
            continue
    if not base_tmp:
        print("  [FAIL] 无法创建自检临时目录")
        return 1
    md_p = Path(base_tmp) / f"_selftest_{uuid.uuid4().hex[:8]}" / "sub" / "list.md"
    try:
        # 收件箱文案取自配置（不写死 raw/_park/downloads —— 该目录已不存在）
        write_manifest([], str(md_p), "夹具", manual_inbox())
        good = md_p.exists()
        print(f"  [{'ok' if good else 'FAIL'}] write_manifest 自建父目录 -> {good}")
        ok = ok and good

        # 正例：**没有 DOI 的失败项也必须带可点击链接**（2026-10-22 定规）
        md2 = Path(base_tmp) / "no-doi.md"
        write_manifest([({"title": "A paper without DOI", "journal": "J",
                          "publication_date": "2026"}, ["x"])],
                       str(md2), "夹具2", manual_inbox())
        txt2 = md2.read_text(encoding="utf-8")
        good2 = "](http" in txt2
        print(f"  [{'ok' if good2 else 'FAIL'}] 无 DOI 的失败项仍带可点击链接 -> {good2}")
        ok = ok and good2
    except Exception as e:                        # noqa: BLE001
        print(f"  [FAIL] write_manifest 自建父目录 -> {type(e).__name__}: {e}")
        ok = False
    finally:
        shutil.rmtree(base_tmp, ignore_errors=True)

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="lit-watch 阶段B 取全文（OA 优先）")
    ap.add_argument("--in", dest="inp", default="", help="阶段A 候选 JSON")
    ap.add_argument("--outdir", default="", help="PDF 落点目录")
    ap.add_argument("--manifest", default="",
                    help="手动下载清单 md 路径（默认 <runs_dir>/downloads/manifest-<时间戳>.md）")
    ap.add_argument("--limit", type=int, default=0, help="最多处理几篇（0=全部）")
    ap.add_argument("--label", default="", help="清单标题里显示的方向标签")
    ap.add_argument("--si-dir", default="", help="补充材料(SI)落点（默认 <outdir>/si）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    # 注：--in/--outdir 原先用 required=True，会让 --selftest 无法单独运行
    #     （argparse 先报缺参、根本到不了自检）。改为在此显式校验。
    if not args.inp or not args.outdir:
        ap.error("必须提供 --in 与 --outdir")

    # 配置只读 tools/lit_config.yaml（本脚本**没有** --config；旧 docstring 写错了）
    try:
        cfg = K.load_lit_config()
    except Exception as e:                        # noqa: BLE001
        ap.error(f"lit 配置无法读取（{type(e).__name__}: {e}）")
    # 机构直链开关：配置 `defaults.institution_proxy`（缺省 True，与旧行为一致）
    inst_proxy = bool((cfg.get("defaults") or {}).get("institution_proxy", True))
    if not inst_proxy:
        print("[info] defaults.institution_proxy=false ⇒ 不尝试出版机构直链", file=sys.stderr)

    data = None
    try:
        data = json.loads(Path(args.inp).read_text(encoding="utf-8"))
    except Exception as e:                        # noqa: BLE001
        ap.error(f"候选 JSON 无法解析：{args.inp}（{type(e).__name__}: {e}）")
    # 🔴 旧实现 `data.get("papers") or []`：JSON 结构不符/为空时**静默空跑**退出 0，
    #    与「本次确实没有候选」不可区分——又是一次把故障读成内容结论。此处明确报错。
    if not isinstance(data, dict):
        ap.error(f"候选 JSON 结构不符：顶层应为对象，实为 {type(data).__name__}：{args.inp}")
    papers = data.get("papers")
    if not isinstance(papers, list) or not papers:
        ap.error(f"候选 JSON 里 papers 为空或缺失（不是「没有候选」，请检查阶段A 产物）：{args.inp}")
    if not any(isinstance(p, dict) and (p.get("title") or p.get("doi")) for p in papers):
        ap.error(f"候选 JSON 里 {len(papers)} 条**均无 title/doi**，疑似解析失败：{args.inp}")
    if args.limit:
        papers = papers[:args.limit]
    outdir = Path(args.outdir)
    outdir.mkdir(parents=True, exist_ok=True)
    # `--si-dir` 的 help 曾写"默认 raw/pdf/si"，实际默认是 `<outdir>/si` —— 现两处一致
    si_dir = Path(args.si_dir) if args.si_dir else (outdir / "si")

    ok, failed, tried = [], [], []
    si_hits, si_failed, si_none = [], [], []
    for i, p in enumerate(papers, 1):
        print(f"[{i}/{len(papers)}] {p.get('title','')[:80]}", flush=True)
        path, info = fetch_one(p, outdir, tried, institution_proxy=inst_proxy, cfg=cfg)
        if path:
            ok.append((p, path, info))
            print(f"  ✅ {Path(path).name}")
            # 🔴 SI 随主文下载（2026-10-22 定规）：**不按 tier**，先判存在再取；
            #    有 SI 但取不到 → 必须进手动下载清单，不得静默。
            si_res = _si_step(path, si_dir)
            if si_res.get("status") == "present":
                si_hits.append((p, si_res["file"]))
                print(f"    📎 SI 已获取：{Path(si_res['file']).name}")
            elif si_res.get("status") == "missing":
                si_failed.append((p, si_res))
                print("    ⚠️ 有 SI 但没取到 —— 已列入手动下载清单")
            elif si_res.get("status") == "no_si":
                si_none.append((p, si_res))
                print("    ⛔ 全文核查无 SI（综述/评论常见），不下载")
        else:
            failed.append((p, info))
            print(f"  ❌ 自动取全文失败（{len(info) if isinstance(info,list) else 1} 个来源均未拿到真 PDF）")
        time.sleep(0.6)   # 温和节流，避免触发风控

    print(f"\n===== 阶段B 结果：成功 {len(ok)} / 失败 {len(failed)} / 共 {len(papers)} =====")
    if failed:
        print("提示：失败项可先试浏览器兜底（真实 Edge + 类人鼠标）："
              "python tools/lit_browser_fetch.py --latest --apply --import")
    for p, path, info in ok:
        print(f"  ✅ {p.get('title','')[:70]}\n     → {Path(path).name}")
    for p, info in failed:
        print(f"  ❌ {p.get('title','')[:70]}\n     DOI: {p.get('doi','—')}")

    result = {"generated": datetime.date.today().isoformat(),
              "ok": [{"title": p.get("title"), "doi": p.get("doi"),
                      "pdf": str(path)} for p, path, _ in ok],
              "si": [{"title": p.get("title"), "doi": p.get("doi"),
                      "si_pdf": str(si)} for p, si in si_hits],
              "si_missing": [{"title": p.get("title"), "doi": p.get("doi"),
                              "reason": r.get("reason", ""),
                              "scan": r.get("scan", {}).get("verdict", "")}
                             for p, r in si_failed],
              "si_not_applicable": [{"title": p.get("title"), "doi": p.get("doi"),
                                     "pages": r.get("scan", {}).get("pages", 0)}
                                    for p, r in si_none],
              "failed": [{"title": p.get("title"), "doi": p.get("doi"),
                          "journal": p.get("journal"), "oa_url": p.get("oa_url"),
                          "reasons": info if isinstance(info, list) else [str(info)]}
                         for p, info in failed]}
    # 🔴 旧实现固定写 `<outdir>/../fetch_result.json`：落点随 outdir 漂移、且每次**覆盖**
    #    上一批的结果（无法回溯）。改为 runs_dir 下的带时间戳文件，并打印路径。
    rdir = result_runs_dir(outdir, cfg)
    rdir.mkdir(parents=True, exist_ok=True)
    rp = rdir / f"fetch_result-{datetime.datetime.now().strftime('%Y%m%d-%H%M%S')}.json"
    rp.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"\n结果 JSON: {rp}")

    if failed:
        # 清单**文件**落 <runs_dir>/downloads（配置派生）；清单里写给用户的 PDF 落点
        # 则是真收件箱 <pdf_dir>/Manual Download（见 manual_inbox 的说明）。
        # （旧实现默认不写清单、且文案指向 outdir —— 用户按指引放好文件收编脚本也扫不到。）
        mpath = args.manifest or os.path.join(
            K.lit_runs_dir(cfg, "downloads"),
            f"manifest-{datetime.datetime.now().strftime('%Y%m%d-%H%M%S')}.md")
        mp = write_manifest(failed, mpath, args.label or data.get("query", ""),
                            manual_inbox(cfg), si_failed=si_failed)
        print(f"手动下载清单(可点开): {mp}")
    elif si_failed:
        # 主文全下到了、但 SI 没取到：同样要落清单（用户规则：取不到必须提醒）
        mpath = args.manifest or os.path.join(
            K.lit_runs_dir(cfg, "downloads"),
            f"manifest-{datetime.datetime.now().strftime('%Y%m%d-%H%M%S')}.md")
        mp = write_manifest([], mpath, args.label or data.get("query", ""),
                            manual_inbox(cfg), si_failed=si_failed)
        print(f"📎 SI 手动下载清单(可点开): {mp}")

    # 🔴 退出码：全失败必须与"跑完了"区分开。
    #    旧实现无条件 `sys.exit(0)` —— 一批 20 篇全被风控挡回来，上层脚本读到的仍是"成功"，
    #    与 CLAUDE.md「失败要能被读出来」直接冲突。4 = 全部失败（与 lit_daily 同一语义）。
    if not ok:
        print(f"[!] 阶段B **全部失败**（{len(failed)}/{len(papers)} 篇均未取到真 PDF）"
              f"⇒ 退出码 4；这通常不是「没有 OA 版本」。先试浏览器兜底：\n"
              f"    python tools/lit_browser_fetch.py --latest --apply --import\n"
              f"    仍失败再按清单人工下载。", file=sys.stderr)
        sys.exit(4)
    sys.exit(0)


if __name__ == "__main__":
    # 🔴 必须 `sys.exit(main())`：直接调用 main() 会丢掉 --selftest 的返回值，
    #    自检 FAIL 也以退出码 0 结束（kb_toolcheck 的"实跑"判据读不出来）。
    sys.exit(main())
